export interface TaskLedgerEvent<TPayload = Record<string, unknown>> {
  workspaceId: string;
  batchIdempotencyKey: string;
  type: string;
  timestamp: string;
  payload: TPayload;
}

export interface WorkingContextProjection {
  workspaceId: string;
  pending: TaskLedgerEvent[];
  accepted: TaskLedgerEvent[];
  events: TaskLedgerEvent[];
}

export interface TaskLedgerWorkingContextOptions {
  workspaceId: string;
}

export function eventBatchKey(event: Pick<TaskLedgerEvent, "batchIdempotencyKey">): string {
  return event.batchIdempotencyKey;
}

export function appendTaskLedgerEvent<T extends TaskLedgerEvent>(
  events: readonly T[],
  event: T,
): T[] {
  if (!event || typeof event !== "object") {
    throw new TypeError("A task ledger event is required");
  }
  if (typeof event.workspaceId !== "string" || event.workspaceId.length === 0) {
    throw new TypeError("workspaceId is required");
  }
  if (typeof event.batchIdempotencyKey !== "string" || event.batchIdempotencyKey.length === 0) {
    throw new TypeError("batchIdempotencyKey is required");
  }
  if (typeof event.type !== "string" || event.type.length === 0) {
    throw new TypeError("event type is required");
  }

  const duplicate = events.some(
    (candidate) =>
      candidate.workspaceId === event.workspaceId &&
      candidate.batchIdempotencyKey === event.batchIdempotencyKey,
  );
  return duplicate ? events.slice() : [...events, event];
}

export function readTaskLedgerEvents<T extends TaskLedgerEvent = TaskLedgerEvent>(
  contents: string,
): T[] {
  if (contents.length === 0) return [];
  const events: T[] = [];\n  const lines = contents.split(/\r?\n/);
  for (const line of lines) {
    if (line.trim().length === 0) continue;
    try {
      events.push(JSON.parse(line) as T);
    } catch {
      throw new SyntaxError("Invalid JSON in task ledger JSONL");
    }
  }
  return events;
}

export function serializeTaskLedgerEvents(events: readonly TaskLedgerEvent[]): string {
  return events.map((event) => JSON.stringify(event)).join("\n") + (events.length > 0 ? "\n" : "");
}

export function projectTaskLedger<T extends TaskLedgerEvent = TaskLedgerEvent>(
  events: readonly T[],
  workspaceId?: string,
): WorkingContextProjection {
  const selected = workspaceId
    ? events.filter((event) => event.workspaceId === workspaceId)
    : events.slice();
  const pending: TaskLedgerEvent[] = [];
  const accepted: TaskLedgerEvent[] = [];

  for (const event of selected) {
    const status =
      event.payload && typeof event.payload === "object"
        ? (event.payload as Record<string, unknown>).status
        : undefined;
    if (status === "accepted" || event.type === "task.accepted" || event.type === "accepted") {
      accepted.push(event);
    } else if (
      status === "pending" ||
      event.type === "task.pending" ||
      event.type === "pending" ||
      event.type === "task.submitted"
    ) {
      pending.push(event);
    }
  }

  return {
    workspaceId: workspaceId ?? selected[0]?.workspaceId ?? "",
    pending,
    accepted,
    events: selected,
  };
}

export class TaskLedgerWorkingContext {
  private readonly events: TaskLedgerEvent[] = [];

  constructor(private readonly options: TaskLedgerWorkingContextOptions) {
    if (!options || typeof options.workspaceId !== "string" || options.workspaceId.length === 0) {
      throw new TypeError("workspaceId is required");
    }
  }

  append(event: TaskLedgerEvent): WorkingContextProjection {
    if (event.workspaceId !== this.options.workspaceId) {
      throw new Error("The event workspace does not match the working context");
    }
    const next = appendTaskLedgerEvent(this.events, event);
    this.events.splice(0, this.events.length, ...next);
    return this.projection();
  }

  read(): TaskLedgerEvent[] {
    return this.events.slice();
  }

  projection(): WorkingContextProjection {
    return projectTaskLedger(this.events, this.options.workspaceId);
  }
}

export default TaskLedgerWorkingContext;

import {
  appendTaskLedgerEvent,
  projectTaskLedger,
  readTaskLedgerEvents,
  serializeTaskLedgerEvents,
  TaskLedgerEvent,
  WorkingContextProjection,
} from "../../shared/task-ledger-working-context";
import { appendFileSync, existsSync, mkdirSync, readFileSync } from "node:fs";
import { dirname, join, resolve } from "node:path";

export interface TaskLedgerWorkingContextOptions {
  workspaceId: string;
  workspaceRoot?: string;
  ledgerDirectory?: string;
}

export interface TaskLedgerWorkingContext {
  append(event: TaskLedgerEvent): WorkingContextProjection;
  read(): TaskLedgerEvent[];
  projection(): WorkingContextProjection;
}

export function taskLedgerPath(
  workspaceRoot: string,
  workspaceId: string,
): string {
  if (typeof workspaceRoot !== "string" || workspaceRoot.length === 0) {
    throw new TypeError("workspaceRoot is required");
  }
  if (typeof workspaceId !== "string" || workspaceId.length === 0) {
    throw new TypeError("workspaceId is required");
  }
  return join(resolve(workspaceRoot), "task-ledger", encodeURIComponent(workspaceId), "events.jsonl");
}

export function readTaskLedger(ledgerPath: string): TaskLedgerEvent[] {
  if (!existsSync(ledgerPath)) return [];
  return readTaskLedgerEvents(readFileSync(ledgerPath, "utf8"));
}

export function appendTaskLedger(ledgerPath: string, event: TaskLedgerEvent): void {
  const events = readTaskLedger(ledgerPath);
  const next = appendTaskLedgerEvent(events, event);
  if (next.length === events.length) return;

  mkdirSync(dirname(ledgerPath), { recursive: true });
  const contents = serializeTaskLedgerEvents(next);
  if (contents.length === 0) return;
  appendFileSync(ledgerPath, `${JSON.stringify(event)}\n`, { encoding: "utf8", flag: "a" });
}

export class ElectronTaskLedgerWorkingContext implements TaskLedgerWorkingContext {
  private readonly ledgerPath: string;

  constructor(private readonly options: TaskLedgerWorkingContextOptions) {
    if (!options || typeof options.workspaceId !== "string" || options.workspaceId.length === 0) {
      throw new TypeError("workspaceId is required");
    }
    const root = options.ledgerDirectory ?? options.workspaceRoot;
    if (!root) throw new TypeError("workspaceRoot or ledgerDirectory is required");
    this.ledgerPath = options.ledgerDirectory
      ? join(resolve(root), "events.jsonl")
      : taskLedgerPath(root, options.workspaceId);
  }

  append(event: TaskLedgerEvent): WorkingContextProjection {
    if (event.workspaceId !== this.options.workspaceId) {
      throw new Error("The event workspace does not match the working context");
    }
    appendTaskLedger(this.ledgerPath, event);
    return this.projection();
  }

  read(): TaskLedgerEvent[] {
    return readTaskLedger(this.ledgerPath).filter(
      (event) => event.workspaceId === this.options.workspaceId,
    );
  }

  projection(): WorkingContextProjection {
    return projectTaskLedger(this.read(), this.options.workspaceId);
  }
}

export function createTaskLedgerWorkingContext(
  options: TaskLedgerWorkingContextOptions,
): ElectronTaskLedgerWorkingContext {
  return new ElectronTaskLedgerWorkingContext(options);
}

export default ElectronTaskLedgerWorkingContext;

